SET @b138_route_client_onboarding_o01 = (SELECT route_id FROM t_gateway_route WHERE route_code = 'client-onboarding-o01');
SET @b138_lookup_guard = (SELECT 1 UNION ALL SELECT 1 FROM DUAL WHERE @b138_perm_client_onboarding_review_read IS NULL OR @b138_perm_client_onboarding_evidence_review IS NULL OR @b138_perm_client_onboarding_classification_edit IS NULL OR @b138_res_client_onboarding_review IS NULL OR @b138_route_client_onboarding_o01 IS NULL);








